const pipelineUpdateJob = `-- name: PipelineUpdateJob :execrows
UPDATE agent_execution_workflows SET status=$3,next_step=$4,last_error=$5,updated_at=$6,finished_at=$7::timestamptz,
 lease_token=NULL,lease_owner=NULL,lease_expires_at=NULL,
 sealed_plan=CASE WHEN $3 IN ('succeeded','failed') THEN NULL ELSE sealed_plan END,
 payload_kid=CASE WHEN $3 IN ('succeeded','failed') THEN '' ELSE payload_kid END
WHERE id=$1 AND lease_token=$2 AND status='running'
`

type PipelineUpdateJobParams struct {
	ID         pgtype.UUID
	LeaseToken pgtype.UUID
	Status     string
	NextStep   int16
	LastError  string
	UpdatedAt  pgtype.Timestamptz
	FinishedAt pgtype.Timestamptz
}

func (q *Queries) PipelineUpdateJob(ctx context.Context, db DBTX, arg PipelineUpdateJobParams) (int64, error) {
	result, err := db.Exec(ctx, pipelineUpdateJob,
		arg.ID,
		arg.LeaseToken,
		arg.Status,
		arg.NextStep,
		arg.LastError,
		arg.UpdatedAt,
		arg.FinishedAt,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

